void plot_image_wall_normal_c(int x, int y) {
    for (int i = 0; i < 240; i++) {
        for (int j = 0; j < 320; j++) {
            plot_pixel(x + j, y + i, wall_normal_c[i * 320 + j]);
        }
    }
}

void erase_image_wall_normal_c(int x, int y) {
    for (int i = 0; i < 240; i++) {
        for (int j = 0; j < 320; j++) {
            plot_pixel(x + j, y + i, 0);
        }
    }
}

